from pathlib import Path
import re
p=Path('work/origins-section.html');s=p.read_text('utf8')
s=s.replace('Рукопись, которую составитель датирует 1700 годом. Текст и родственные связи переданы по семейному исследованию.','Запись 1700 года о Макаре Маршалкине и его сыновьях Андрее, Кирилле и Корнее в Обояни.').replace('1700 · по датировке составителя','1700 · Обоянь').replace('Вероятно, 1785 год','1785 год')
s=re.sub(r'<div><strong>Для семьи</strong>.*?Дата перехода ещё уточняется.*?</div>','',s,flags=re.S)
s=s.replace('Константин Трутовский. «Переселенцы из Курской губернии», 1864. Картина передаёт переживание отъезда и используется как художественная иллюстрация семейного переселения XVIII века.','Примерно таким же образом, с семьями и домашним скарбом на обозах, Маршалкины переселялись на Кавказ. Художественная иллюстрация переезда.').replace('К. А. Трутовский · Переселенцы из Курской губернии · 1864','Переселение семьи на Кавказ · художественная иллюстрация')
