p=Path('work/familio_enrich.py');s=p.read_text('utf8').replace('Просмотрены все 28 страниц доступного каталога: 556 записей, из них 473 внесены Денисом Маршалкиным. Ниже — 12 сопоставленных карточек с дополнительными сведениями и пояснениями. Это пользовательское семейное исследование: ссылки на архивы и воспоминания сохраняют свою степень достоверности.','За каждой ветвью древа — занятия, переезды и семейные воспоминания. Дополнительные записи Дениса Маршалкина в Familio помогают увидеть за именами судьбы: железную дорогу, авиационный завод, науку, военную службу и домашнюю жизнь.');p.write_text(s,'utf8')
